'use strict';
// Offline build: fully local. Reads the banner from src/banner.js and writes dist/bundle.js.
const fs = require('fs');
const path = require('path');
const { BANNER } = require('../src/banner.js');

function main() {
  const dist = path.join(__dirname, '..', 'dist');
  fs.mkdirSync(dist, { recursive: true });
  const contents = [
    '/* generated by scripts/build-offline.js — do not edit by hand */',
    BANNER,
    'bundle: ok',
    '',
  ].join('\n');
  fs.writeFileSync(path.join(dist, 'bundle.js'), contents);
  console.log('offline build wrote dist/bundle.js');
}

if (require.main === module) main();
